import json, itertools, os

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "re.json")
R = []


def idx(r, c):
    return 1 + 9 * r + c


CK, CQ, Ck, Cq, EP = 73, 74, 75, 76, 78
FILES = "abcdefgh"

# --- setup: "@<board 71> <castling4> <epfile|->\n"
R.append([r"^(\S+) w (\S+) ([a-h])6(?: \S+ \S+)?$", r"@\1 \2 \3\n"])
R.append([r"^(\S+) w (\S+) -(?: \S+ \S+)?$", r"@\1 \2 -\n"])
for d in range(1, 9):
    R.append([str(d), "." * d])
combos = []
for bits in itertools.product([0, 1], repeat=4):
    full = "".join(ch if b else "-" for ch, b in zip("KQkq", bits))
    short = "".join(ch for ch, b in zip("KQkq", bits)) or "-"
    combos.append((full, short))
for full, short in combos:
    if full != short:
        R.append([" " + short + " ", " " + full + " "])


def gen(conds, mods, marker="#"):
    pat = "(?m)^(@"
    for i, cls in sorted(conds.items()):
        pat += "(?=.{%d}%s)" % (i - 1, cls)
    rep_new = "\\n" + marker
    pos = 1
    g = 2
    for i in sorted(mods):
        pat += "(.{%d})." % (i - pos)
        rep_new += "\\g<%d>" % g + mods[i]
        g += 1
        pos = i + 1
    pat += "([^\\n]*))"
    rep_new += "\\g<%d>" % g
    R.append([pat, "\\g<1>" + rep_new])


def inb(r, c):
    return 0 <= r < 8 and 0 <= c < 8


def castle_mods(s, t, piece):
    m = {}
    if piece == "K" and s == idx(7, 4):
        m[CK] = "-"
        m[CQ] = "-"
    if s == idx(7, 7) or t == idx(7, 7):
        m[CK] = "-"
    if s == idx(7, 0) or t == idx(7, 0):
        m[CQ] = "-"
    if t == idx(0, 7):
        m[Ck] = "-"
    if t == idx(0, 0):
        m[Cq] = "-"
    return m


def piece_move(P, s, t, between):
    conds = {s: P, t: "[.a-z]"}
    for b in between:
        conds[b] = r"\."
    mods = {s: ".", t: P, EP: "-"}
    mods.update(castle_mods(s, t, P))
    gen(conds, mods)


KN = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
KG = [(a, b) for a in (-1, 0, 1) for b in (-1, 0, 1) if (a, b) != (0, 0)]
ORT = [(0, 1), (0, -1), (1, 0), (-1, 0)]
DIA = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

for r in range(8):
    for c in range(8):
        s = idx(r, c)
        for P, dirs, slide in (
            ("N", KN, False),
            ("K", KG, False),
            ("R", ORT, True),
            ("B", DIA, True),
            ("Q", ORT + DIA, True),
        ):
            for dr, dc in dirs:
                between = []
                rr, cc = r + dr, c + dc
                while inb(rr, cc):
                    piece_move(P, s, idx(rr, cc), list(between))
