gen(
    {CK: "K", idx(7, 4): "K", idx(7, 5): r"\.", idx(7, 6): r"\.", idx(7, 7): "R"},
    {idx(7, 5): "K", idx(7, 6): "K", CK: "-", CQ: "-", EP: "-"},
    "$",
)
gen(
    {
        CQ: "Q",
        idx(7, 4): "K",
        idx(7, 3): r"\.",
        idx(7, 2): r"\.",
        idx(7, 1): r"\.",
        idx(7, 0): "R",
    },
    {idx(7, 3): "K", idx(7, 2): "K", CK: "-", CQ: "-", EP: "-"},
    "$",
)


# attack check: delete any generated line where some white K is attacked
def L(i, cls):
    return "(?=.{%d}%s)" % (i - 1, cls)


for r in range(8):
    for c in range(8):
        ks = idx(r, c)
        alts = []
        for dc in (-1, 1):
            if inb(r - 1, c + dc):
                alts.append(L(idx(r - 1, c + dc), "p"))
        for dr, dc in KN:
            if inb(r + dr, c + dc):
                alts.append(L(idx(r + dr, c + dc), "n"))
        for dr, dc in KG:
            if inb(r + dr, c + dc):
                alts.append(L(idx(r + dr, c + dc), "k"))
        for dirs, cls in ((ORT, "[rq]"), (DIA, "[bq]")):
            for dr, dc in dirs:
                between = []
                rr, cc = r + dr, c + dc
                while inb(rr, cc):
                    alts.append(
                        "".join(L(b, r"\.") for b in between) + L(idx(rr, cc), cls)
                    )
                    between.append(idx(rr, cc))
                    rr += dr
                    cc += dc
        R.append(
            ["(?m)^[#$]" + L(ks, "K") + "(?:" + "|".join(alts) + ")[^\\n]*\\n", ""]
        )

# castling fixups
R.append([r"(?m)^\$(.{67})KKKR", r"#\g<1>.RK."])
R.append([r"(?m)^\$(.{63})R\.KKK", r"#\g<1>..KR."])

# output formatting
R.append([r"(?m)^@[^\n]*\n", ""])
for d in range(8, 0, -1):
    R.append([r"\.{%d}" % d, str(d)])
for full, short in combos:
    if full != short:
        R.append([" " + full + " ", " " + short + " "])
R.append([r"(?m) ([a-h])$", r" \g<1>3"])
R.append([r"(?m)^#(\S+) (\S+) (\S+)$", r"\1 b \2 \3 0 1"])
R.append([r"\n\Z", ""])
json.dump(R, open(OUT, "w"))
print(len(R), os.path.getsize(OUT))

